'use strict';
const units=window.REVIEW_UNITS,E=window.ReviewEngine;
const main=document.querySelector('main');let KEY=window.Learner.key();
const empty=()=>({version:2,read:[],attempts:{},mistakes:[],draws:{},readCards:[]});
let saved=empty(),storageOK=true;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.read)&&s.attempts&&Array.isArray(s.mistakes))saved={...empty(),...s,version:s.version||1};}catch{storageOK=false;}
const oldIds={'N1-01':'u0-t01-a','N1-02':'u0-t03-a','N1-03':'u0-t13-a','N1-04':'u0-t15-b','N2-01':'u1-t05-a','N2-02':'u1-t07-b','N2-03':'u1-t16-a','N2-04':'u1-t18-a','S1-01':'u2-t07-b','S1-02':'u2-t08-b','S1-03':'u2-t11-a','S1-04':'u2-t17-b','S2-01':'u3-t05-a','S2-02':'u3-t06-a','S2-03':'u3-t12-a','S2-04':'u3-t16-a'};
if(saved.version!==2){saved.mistakes=saved.mistakes.map(id=>oldIds[id]||id);saved.read=[];saved.version=2;}
const questionIds=new Set(units.flatMap(u=>u.questions.map(q=>q.id)));
saved.mistakes=[...new Set(saved.mistakes)].filter(id=>questionIds.has(id));
for(const a of Object.values(saved.attempts)){if(a.bestPct===undefined)a.bestPct=Math.round(a.best/a.total*100);}
let filter='全部',currentUnit=null,quiz=null,studyPage=0,practiceCount=20;
const letters='ABCD';
const typeNames={single:'單選題',boolean:'是非題',multiple:'多選題',matching:'配對題'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{storageOK=false;}}
const allQuestions=()=>units.flatMap(u=>u.questions);
function updateCount(){document.querySelector('#wrong-count').textContent=saved.mistakes.length;}
function focusMain(){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
function go(view,focus=true){window.studyInProgress=false;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));updateCount();if(view==='home')home();if(view==='mistakes')mistakes();if(view==='progress'){progress();renderRecords();}if(focus)focusMain();}
function home(){const done=Object.keys(saved.attempts).length;main.innerHTML=`<section class="intro"><div><span class="eyebrow">YOUR LITTLE LEARNING CORNER</span><h1>${Learner.getName()?esc(Learner.getName())+"，":""}今天也進步一點。</h1><p>80 個重點提醒、400 道題目，陪你把觀念越練越熟。</p></div><span class="date-chip">五年級上學期・自然 × 社會</span></section><section class="hero"><div class="hero-text"><span class="eyebrow">A LITTLE EVERY DAY</span><h2>每次一點新挑戰，<br>把「不熟」練成「我會」。</h2><p>讀重點，隨機練習；每次出發，都有不同題目。</p><button class="primary" id="start">開始今天的複習 <span>↗</span></button></div>${illustration()}</section><section class="stats" aria-label="學習概況"><div class="stat"><span class="stat-icon">▧</span><div><strong>${saved.readCards.length}<small>/ 80 個</small></strong><p>已讀重點提醒</p></div></div><div class="stat"><span class="stat-icon">✓</span><div><strong>${done}<small>/ 4 單元</small></strong><p>已完成練習</p></div></div><div class="stat"><span class="stat-icon">↻</span><div><strong>${saved.mistakes.length}<small>題</small></strong><p>等你再挑戰</p></div></div></section><section><div class="section-head"><h2>選一個單元出發<span>每單元都有 100 題可練習。</span></h2><div class="tabs" aria-label="科目篩選">${['全部','自然','社會'].map(f=>`<button aria-pressed="${filter===f}" class="${filter===f?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div></div><div class="units">${units.filter(u=>filter==='全部'||u.subject===filter).map(u=>`<article class="unit-card">${saved.attempts[u.id]?'<span class="unit-done">✓ 已練習</span>':''}<div class="unit-top"><div class="unit-illustration ${u.color}">${icon(u.id)}</div><div><span class="unit-meta">${u.subject} · 第 ${u.number} 單元</span><h3>${u.name}</h3></div></div><p class="unit-desc">${u.cards.slice(0,3).map(c=>c.title).join('　·　')}</p><div class="unit-foot"><span>20 個重點　·　100 題題庫</span><button class="link-button" data-unit="${u.id}" aria-label="開始複習${u.name}">開始複習　→</button></div></article>`).join('')}</div></section><p class="bottom-note"><span>✧</span> 單選、是非、多選、配對，每次練習都有新收穫。</p>`;document.querySelector('#start').onclick=()=>study(units.find(u=>!saved.attempts[u.id])?.id??0);main.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;home();});bindUnits();}
function bindUnits(){main.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>study(Number(b.dataset.unit)));}
function unitHeader(u){return `<button class="back" id="back">← 回到複習桌</button><div class="study-header"><div class="unit-illustration ${u.color}">${icon(u.id)}</div><div><span class="eyebrow">${u.subject} · 第 ${u.number} 單元</span><h1>${u.name}</h1><p>20 個重點提醒 · 100 題題庫 · 四種題型</p></div></div>`;}
function study(id,page=0){currentUnit=units[id];studyPage=page;const u=currentUnit;const pageCards=u.cards.slice(page*5,page*5+5);main.innerHTML=unitHeader(u)+`<div class="study-tabs"><button class="selected" aria-current="page">01　讀重點</button><button id="quiz-tab">02　隨機練習</button></div><div class="reading-nav" aria-label="重點分頁">${[0,1,2,3].map(p=>`<button data-page="${p}" class="${p===page?'selected':''}" aria-current="${p===page?'page':'false'}">重點 ${p*5+1}～${p*5+5}</button>`).join('')}<span>已讀 ${u.cards.filter(c=>saved.readCards.includes(c.id)).length} / 20</span></div><div class="cards-grid">${pageCards.map((c,i)=>`<article class="knowledge"><div class="card-topline"><span class="card-number">KEY POINT ${String(page*5+i+1).padStart(2,'0')}</span><button class="read-toggle ${saved.readCards.includes(c.id)?'done':''}" data-read="${c.id}" aria-pressed="${saved.readCards.includes(c.id)}">${saved.readCards.includes(c.id)?'✓ 已讀':'標記已讀'}</button></div><h3>${c.title}</h3><p>${c.text}</p></article>`).join('')}</div><div class="reading-actions"><button class="secondary" id="mark-page">這 5 個重點讀好了 ✓</button>${page<3?'<button class="link-button" id="next-page">下一組重點 →</button>':''}</div><section class="tip-box"><h3>✧　這些地方，留意一下</h3><ul>${u.tips.map(t=>`<li>${t}</li>`).join('')}</ul></section><div class="practice-banner"><div><h3>準備好，來一份不同的練習。</h3><p>單選、是非、多選與配對混合出題，優先抽還沒練過的題目。</p></div><button class="primary" id="practice-open">選擇練習題數 →</button></div>`;document.querySelector('#back').onclick=()=>go('home');document.querySelector('#quiz-tab').onclick=document.querySelector('#practice-open').onclick=()=>practiceSetup(id);main.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{study(id,Number(b.dataset.page));focusMain();});main.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{const cid=b.dataset.read;if(saved.readCards.includes(cid))saved.readCards=saved.readCards.filter(x=>x!==cid);else saved.readCards.push(cid);syncRead(id);persist();study(id,page);});document.querySelector('#mark-page').onclick=()=>{pageCards.forEach(c=>{if(!saved.readCards.includes(c.id))saved.readCards.push(c.id);});syncRead(id);persist();study(id,page);};if(page<3)document.querySelector('#next-page').onclick=()=>{study(id,page+1);focusMain();};focusMain();}
function syncRead(id){if(units[id].cards.every(c=>saved.readCards.includes(c.id))){if(!saved.read.includes(id))saved.read.push(id);}else saved.read=saved.read.filter(x=>x!==id);}
function practiceSetup(id){currentUnit=units[id];const u=currentUnit;main.innerHTML=unitHeader(u)+`<section class="quiz-panel setup-panel"><span class="eyebrow">A FRESH MIX, EVERY TIME</span><h2>今天想練幾題？</h2><p class="muted">從 ${u.questions.length} 題題庫抽出你的練習。題型平均搭配，選項也會重新排列。</p><div class="count-options" role="group" aria-label="練習題數">${[10,20,40].map(n=>`<button data-count="${n}" class="${practiceCount===n?'selected':''}" aria-pressed="${practiceCount===n}"><strong>${n}</strong> 題<small>${n===10?'輕量暖身':n===20?'均衡複習':'加深練習'}</small></button>`).join('')}</div><div class="mix-preview">${mixPreview(practiceCount)}</div><p class="draw-note">本單元已抽過 ${new Set(saved.draws[id]?.seen||[]).size} / 100 題。優先使用未練題目，並避開上一份練習的題目。</p><p class="rule-note">每題 1 分。多選題須選齊正確選項；配對題須全部配對正確。</p><button class="primary" id="begin">開始隨機 ${practiceCount} 題 <span>→</span></button><button class="text-button setup-back" id="read-back">先回去看重點</button></section>`;document.querySelector('#back').onclick=()=>go('home');main.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{practiceCount=Number(b.dataset.count);practiceSetup(id);});document.querySelector('#begin').onclick=()=>newPractice(id);document.querySelector('#read-back').onclick=()=>study(id,studyPage);focusMain();}
function mixPreview(n){return `<span>單選 ${n*.4}</span><span>是非 ${n*.2}</span><span>多選 ${n*.2}</span><span>配對 ${n*.2}</span>`;}
function newPractice(id){if(!Learner.getName()){Learner.showName();return;}const history=saved.draws[id]||{seen:[],last:[]};const picked=E.sample(units[id].questions,practiceCount,history);saved.draws[id]={seen:[...new Set([...history.seen,...picked.map(q=>q.id)])],last:picked.map(q=>q.id)};persist();startQuiz(picked,false,id);}
function initialSelection(q){return q.type==='matching'?q.left.map(()=>null):q.type==='multiple'?[]:null;}
function startQuiz(questions,review,unitId=null){if(!questions.length){go('mistakes');return;}window.studyInProgress=true;quiz={questions:E.shuffle(questions).map(q=>E.prepare(q)),index:0,checked:false,results:[],review,unitId,sessionId:Learner.uuid(),startedAt:Date.now(),questionStartedAt:Date.now()};quiz.selected=initialSelection(quiz.questions[0]);renderQuiz();focusMain();}
function answerText(q){if(q.type==='matching')return q.left.map((l,i)=>`${l} → ${q.options[q.answer[i]]}`).join('；');const ids=Array.isArray(q.answer)?q.answer:[q.answer];return ids.map(i=>`${letters[i]}．${q.options[i]}`).join('、');}
function renderQuiz(){const q=quiz.questions[quiz.index],u=units[q.unit],isRight=quiz.checked&&E.correct(q,quiz.selected);const help={single:'選擇一個最合適的答案。',boolean:'判斷這句話是否正確。',multiple:'請選出兩個正確選項，選齊才算答對。',matching:'每個項目選一個說明，三組全對才算答對。'};main.innerHTML=unitHeader(u)+`<div class="quiz-panel"><div class="quiz-meta"><span>${quiz.review?'錯題再挑戰':'隨機練習'} · ${q.concept}</span><span>第 ${quiz.index+1} / ${quiz.questions.length} 題</span></div><div class="progress-track"><div style="width:${quiz.index/quiz.questions.length*100}%"></div></div><span class="type-badge">${typeNames[q.type]}</span><h2 class="question">${q.text}</h2><p class="question-help">${help[q.type]}</p>${q.type==='matching'?`<div class="match-grid">${q.left.map((l,i)=>`<label class="match-row"><span>${i+1}．${l}</span><select data-match="${i}" aria-label="${esc(l)}的配對說明" ${quiz.checked?'disabled':''}><option value="">請選擇說明</option>${q.options.map((o,j)=>`<option value="${j}" ${quiz.selected[i]===j?'selected':''}>${o}</option>`).join('')}</select>${quiz.checked?`<small class="${quiz.selected[i]===q.answer[i]?'match-right':'match-wrong'}">${quiz.selected[i]===q.answer[i]?'✓ 正確':'正確：'+q.options[q.answer[i]]}</small>`:''}</label>`).join('')}</div>`:`<div class="options" role="group" aria-label="答案選項">${q.options.map((o,i)=>{const selected=Array.isArray(quiz.selected)?quiz.selected.includes(i):quiz.selected===i,correct=Array.isArray(q.answer)?q.answer.includes(i):q.answer===i;return `<button class="option ${selected?'chosen':''} ${quiz.checked&&correct?'correct':''} ${quiz.checked&&selected&&!correct?'incorrect':''}" data-option="${i}" aria-pressed="${selected}" ${quiz.checked?'disabled':''}><span class="letter">${q.type==='multiple'?(selected?'☑':'☐'):letters[i]}</span><span>${o}</span></button>`;}).join('')}</div>`}${quiz.checked?`<div class="feedback ${isRight?'':'wrong'}" role="status"><strong>${isRight?'✓ 答對了，你掌握這個觀念了！':'再理解一下，就會更熟悉。'}</strong>${!isRight?`<p class="answer-line">正確答案：${answerText(q)}</p>`:''}<p>${q.explanation}</p></div>`:''}<div class="quiz-actions"><span class="muted">${quiz.checked?'看完解析，再繼續下一步。':q.type==='multiple'?`目前已選 ${quiz.selected.length} 項`:'慢慢想，不用急著回答。'}</span><button class="primary" id="submit" ${!E.ready(q,quiz.selected)?'disabled':''}>${quiz.checked?(quiz.index===quiz.questions.length-1?'看看練習成果':'下一題'):'確認答案'} <span>→</span></button></div></div>`;document.querySelector('#back').onclick=()=>go(quiz.review?'mistakes':'home');main.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.option);if(q.type==='multiple'){if(quiz.selected.includes(i))quiz.selected=quiz.selected.filter(v=>v!==i);else quiz.selected.push(i);}else quiz.selected=i;renderQuiz();main.querySelector(`[data-option="${i}"]`)?.focus({preventScroll:true});});main.querySelectorAll('[data-match]').forEach(s=>s.onchange=()=>{quiz.selected[Number(s.dataset.match)]=s.value===''?null:Number(s.value);document.querySelector('#submit').disabled=!E.ready(q,quiz.selected);});document.querySelector('#submit').onclick=()=>{if(!quiz.checked){if(!E.ready(q,quiz.selected))return;quiz.checked=true;const right=E.correct(q,quiz.selected);quiz.results.push({id:q.id,correct:right});Learner.log({kind:"answer",sessionId:quiz.sessionId,subject:u.subject,unitName:u.name,questionId:q.id,questionType:q.type,question:q.text,selected:selectionText(q,quiz.selected),expected:selectionText(q,q.answer),correct:right,elapsedSeconds:(Date.now()-quiz.questionStartedAt)/1000});if(!right&&!saved.mistakes.includes(q.id))saved.mistakes.push(q.id);if(right)saved.mistakes=saved.mistakes.filter(id=>id!==q.id);persist();updateCount();renderQuiz();document.querySelector('.feedback')?.scrollIntoView({block:'nearest',behavior:'instant'});}else if(quiz.index===quiz.questions.length-1)finish();else{quiz.index++;quiz.questionStartedAt=Date.now();quiz.checked=false;quiz.selected=initialSelection(quiz.questions[quiz.index]);renderQuiz();focusMain();}};}
function finish(){window.studyInProgress=false;const right=quiz.results.filter(r=>r.correct).length,total=quiz.results.length,pct=Math.round(right/total*100);Learner.log({kind:"session",sessionId:quiz.sessionId,subject:[...new Set(quiz.questions.map(q=>units[q.unit].subject))].join("／"),unitName:quiz.review?"錯題再練":units[quiz.unitId].name,score:pct,right,total,elapsedSeconds:(Date.now()-quiz.startedAt)/1000});if(!quiz.review){const old=saved.attempts[quiz.unitId];saved.attempts[quiz.unitId]={last:right,total,bestPct:Math.max(old?.bestPct??0,pct),count:(old?.count??0)+1,date:new Date().toISOString()};}persist();const wrong=quiz.results.filter(r=>!r.correct),wrongBank=allQuestions().filter(q=>wrong.some(w=>w.id===q.id));main.innerHTML=`<button class="back" id="back">← 回到複習桌</button><section class="result"><div class="result-symbol">${right===total?'✧':'✓'}</div><span class="eyebrow">ONE MORE LITTLE STEP</span><h2>${right===total?'這次的觀念，都掌握了！':'完成了，又前進一小步。'}</h2><p>${wrong.length?'不熟悉的題目已放進錯題本，隨時可以再挑戰。':'再換一組題目，試試把觀念用在不同情境。'}</p><div class="score">${right}<small> / ${total} 題答對（${pct} 分）</small></div><div class="result-actions">${wrong.length?'<button class="primary" id="retry-wrong">再練這次錯題 ↻</button>':''}<button class="${wrong.length?'secondary':'primary'}" id="new-set">${quiz.review?'回到錯題本':'換一份新題目 →'}</button><button class="secondary" id="home">回到複習桌</button></div><div class="type-results">${['single','boolean','multiple','matching'].map(type=>{const rs=quiz.results.filter(r=>quiz.questions.find(q=>q.id===r.id).type===type);return rs.length?`<span>${typeNames[type]} ${rs.filter(r=>r.correct).length} / ${rs.length}</span>`:'';}).join('')}</div><details class="result-summary"><summary>查看這次 ${total} 題的練習紀錄</summary>${quiz.results.map(r=>{const q=quiz.questions.find(q=>q.id===r.id);return `<p>${r.correct?'✓':'○'}　${q.concept} · ${typeNames[q.type]}<span class="muted">　${r.correct?'已掌握':'再練習'}</span></p>`;}).join('')}</details></section>`;document.querySelector('#back').onclick=document.querySelector('#home').onclick=()=>go('home');if(wrong.length)document.querySelector('#retry-wrong').onclick=()=>startQuiz(wrongBank,true);document.querySelector('#new-set').onclick=()=>quiz.review?go('mistakes'):newPractice(quiz.unitId);updateCount();focusMain();}
function mistakes(){const qs=allQuestions().filter(q=>saved.mistakes.includes(q.id));main.innerHTML=`<section class="intro"><div><span class="eyebrow">A SECOND TRY, A NEW DISCOVERY</span><h1>我的錯題練習本</h1><p>保留 ${qs.length} 道待複習題，答對後就會從這裡畢業。每次最多練 20 題。</p></div>${qs.length?'<button class="primary" id="practice-wrong">開始錯題再練 →</button>':''}</section>${qs.length?`<div class="mistake-list">${qs.map(q=>`<article class="mistake-row"><span class="unit-meta">${units[q.unit].subject} · ${units[q.unit].name} · ${typeNames[q.type]}</span><h3>${q.text}</h3><p>先想一想，開始練習後再看答案與解析。</p></article>`).join('')}</div>`:'<section class="empty"><div class="result-symbol">✧</div><h2>目前沒有等待複習的錯題。</h2><p>完成單元練習後，不熟悉的題目會自動留在這裡。</p><button class="primary" id="empty-home">去選一個單元 →</button></section>'}`;if(qs.length)document.querySelector('#practice-wrong').onclick=()=>startQuiz(E.shuffle(qs).slice(0,20),true);else document.querySelector('#empty-home').onclick=()=>go('home');}
function progress(){main.innerHTML=`<section class="intro"><div><span class="eyebrow">EVERY LITTLE STEP COUNTS</span><h1>我的學習足跡</h1><p>看見每一個讀過的重點，以及每一份練習的進步。</p></div></section>${units.map(u=>{const a=saved.attempts[u.id],read=u.cards.filter(c=>saved.readCards.includes(c.id)).length,seen=new Set(saved.draws[u.id]?.seen||[]).size;return `<article class="progress-row"><div class="unit-illustration ${u.color}">${icon(u.id)}</div><div><h3>${u.subject} · ${u.name}</h3><p>重點已讀 ${read} / 20 · 已抽題 ${seen} / 100</p><p>${a?`練習 ${a.count} 次 · 最近 ${a.last} / ${a.total} 題 · 最佳 ${a.bestPct} 分`:'尚未完成練習'}</p></div><button class="link-button" data-unit="${u.id}">再出發 →</button></article>`;}).join('')}<p class="bottom-note">進度保存在本機瀏覽器，換裝置不會自動同步。</p>`;bindUnits();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelector('.brand').onclick=e=>{e.preventDefault();go('home');};
const info=document.querySelector('#info');document.querySelector('#about').onclick=()=>{document.querySelector('#storage-note').textContent=storageOK?'':'目前瀏覽器無法儲存紀錄，離開頁面後進度可能遺失。';info.showModal();};document.querySelector('.close').onclick=()=>info.close();
document.querySelector('#reset').onclick=()=>{if(confirm('要清除這位小朋友在本機的閱讀進度、練習成績與錯題嗎？已保存的逐題作答與待同步資料會保留。')){saved=empty();persist();info.close();go('home');}};
window.onLearnerChanged=()=>{quiz=null;window.studyInProgress=false;KEY=Learner.key();saved=empty();try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.read)&&s.attempts&&Array.isArray(s.mistakes))saved={...empty(),...s};}catch{storageOK=false;}go('home');};
function selectionText(q,selected){if(q.type==='matching')return q.left.map((l,i)=>l+' → '+(q.options[selected[i]]||'未作答'));return (Array.isArray(selected)?selected:[selected]).map(i=>q.options[i]||'未作答');}
function renderRecords(){const records=Learner.records(),sessions=records.filter(e=>e.kind==='session').slice(-10).reverse();const section=document.createElement('section');section.className='record-summary';section.innerHTML='<h2>'+esc(Learner.getName())+'的作答紀錄</h2><p>本機已保存 '+records.filter(e=>e.kind==='answer').length+' 筆逐題作答，及 '+records.filter(e=>e.kind==='session').length+' 次完成練習。</p><div class="record-scroll"><table><thead><tr><th>時間</th><th>單元</th><th>成績</th></tr></thead><tbody>'+sessions.map(e=>'<tr><td>'+esc(new Date(e.createdAt).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}))+'</td><td>'+esc(e.unitName)+'</td><td>'+e.score+' 分（'+e.right+' / '+e.total+'）</td></tr>').join('')+'</tbody></table></div><p class="table-note">'+(sessions.length?'顯示最近 10 次完成的練習。':'完成一份練習後，這裡就會留下紀錄。')+'<br>孩子的紀錄依名字分開；家長可在 Google 試算表查看已同步的逐題作答。</p>';main.appendChild(section);}
persist();go('home',false);
